starter:
n = int(input())
groups = {}

# 조 번호를 키로, 이름 리스트를 값으로 모아보세요.

solution:
n = int(input())
groups = {}
for _ in range(n):
    team, name = input().split()
    team = int(team)
    if team not in groups:
        groups[team] = []
    groups[team].append(name)

for team in sorted(groups):
    names = sorted(groups[team])
    print(f"{team}조: " + " ".join(names))
